-- MoonDuels background image
do
    local SADO_BG_FILE = "MOONDUELS_BG.jpg"
    local SADO_BG_B64 = ""
    local function sadoBgAsset()
        local loader = getcustomasset or getsynasset
        if type(loader) ~= "function" or type(writefile) ~= "function" then return nil end
        pcall(function()
            local data
            if crypt and crypt.base64decode then
                data = crypt.base64decode(SADO_BG_B64)
            elseif base64 and base64.decode then
                data = base64.decode(SADO_BG_B64)
            else
                local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
                local raw = SADO_BG_B64:gsub("[^"..b.."=]", "")
                local out = {}
                for i = 1, #raw, 4 do
                    local n = 0
                    for j = 0, 3 do
                        local ch = raw:sub(i+j, i+j)
                        local v = b:find(ch, 1, true)
                        if v then n = n * 64 + (v - 1) elseif ch == "=" then n = n * 64 end
                    end
                    table.insert(out, string.char(math.floor(n / 65536) % 256))
                    if raw:sub(i+2, i+2) ~= "=" then table.insert(out, string.char(math.floor(n / 256) % 256)) end
                    if raw:sub(i+3, i+3) ~= "=" then table.insert(out, string.char(n % 256)) end
                end
                data = table.concat(out)
            end
            if type(data) == "string" and #data > 64 then writefile(SADO_BG_FILE, data) end
        end)
        local ok, asset = pcall(loader, SADO_BG_FILE)
        if ok and type(asset) == "string" then return asset end
        return nil
    end
    local asset = sadoBgAsset()
    if asset then BirdImage.Image = asset end
end

